#include<bits/stdc++.h>

using namespace std;

int main(){
  int t;
  cin >> t;
  for(int tr=0;tr<t;tr++){
    int n;
    string s;
    cin >> n >> s;

    s="."+s+".";
    vector<int> lp(n+1,0),rp(n+1,0);
    for(int i=1;i<n;i++){
      if(s[i]=='L'){
        lp[i]=lp[i-1]+1;
      }
      if(s[i]=='R'){
        rp[i]=rp[i-1]+1;
      }
    }
    vector<int> ls(n+1,0),rs(n+1,0);
    for(int i=n-1;i>=1;i--){
      if(s[i]=='L'){
        ls[i]=ls[i+1]+1;
      }
      if(s[i]=='R'){
        rs[i]=rs[i+1]+1;
      }
    }

    vector<int> bk(n+1,0);
    for(int i=0;i<n;i++){
      int l=0,r=n-1;
      l+=(rp[i]+ls[i+1]);
      r-=(lp[i]+rs[i+1]);
      bk[l]++;
      bk[r+1]--;
    }
    for(int i=0;i<n;i++){
      if(i){
        cout << " ";
        bk[i]+=bk[i-1];
      }
      cout << bk[i];
    }cout << "\n";
  }
 return 0;
}
